  QObject::connect(histories,&QComboBox::currentIndexChanged,q,[this]{if(rendering)return;historyId=histories->currentData().toString();renderHistory();});QObject::connect(removeHistory,&QPushButton::clicked,q,[this]{if(!active||!q->isVisible()||busy||historyId.isEmpty())return;if(QMessageBox::question(q,"删除本机历史","仅删除此目录观测历史，当前目录和候选不删除。是否确认？")!=QMessageBox::Yes)return;QJsonArray kept;for(auto v:state.value("history").toArray())if(v.toObject().value("id").toString()!=historyId)kept.append(v);auto updated=state;double revision=state.value("revision").toDouble();updated.insert("history",kept);updated.insert("revision",revision+1);run([this,updated,revision](const Cancel& c){store.save(updated,revision,c);return store.read(c);},[this](QJsonObject value){historyId.clear();accept(value);});});QObject::connect(previewButton,&QPushButton::clicked,q,[this]{try{q->previewImport(importText->fullBytes());}catch(const std::exception& e){error(e);}});QObject::connect(confirmImport,&QPushButton::clicked,q,[this]{if(!active||!q->isVisible()||busy||pending.isEmpty())return;auto p=pending;run([this,p](const Cancel& c){store.apply(p,c);return store.read(c);},[this](QJsonObject value){pending={};accept(value);importState->setText("已确认合并；旧条目/候选不覆盖，外部记录仍标未本轮验证");});});QObject::connect(showExport,&QPushButton::clicked,q,[this]{try{cancel();importText->setFullText(QString::fromUtf8(q->exportArchive()));pending={};deferred.clear();importState->setText("完整发现档案已显示（目录/候选/历史），未截断；不含成分缓存");controls();}catch(const std::exception& e){error(e);}});QObject::connect(fileExport,&QPushButton::clicked,q,[this]{try{auto bytes=q->exportArchive();QString path=QFileDialog::getSaveFileName(q,"导出新发现JSON文件",{},"JSON (*.json)");if(path.isEmpty())return;require(!QFileInfo::exists(path),"目标存在，请选择新文件名");QTemporaryFile temp(QFileInfo(path).absolutePath()+"/.discovery-export-XXXXXX");require(temp.open()&&temp.write(bytes)==bytes.size()&&temp.flush(),"完整档案写入失败");temp.close();require(!QFileInfo::exists(path)&&temp.rename(path),"完整档案发布失败，未覆盖");temp.setAutoRemove(false);importState->setText("完整发现档案已导出本机JSON");}catch(const std::exception& e){error(e);}});importText->onEdited=[this]{if(rendering)return;cancel();pending={};deferred.clear();importState->setText("JSON已编辑，请重新预览；旧预览不会提交");controls();};QObject::connect(tabs,&QTabWidget::currentChanged,q,[this](int index){if(index==3&&!busy)renderHistory();});controls();load();
